# Phase 428 in CLAUDE.md: Book rule 8 names the ledger line, and the Phase row.   python3 claudemd428.py <CLAUDE.md>
import sys
p = sys.argv[1]; s = open(p, encoding='utf-8').read()
def rep(a, b):
    global s
    if s.count(a) != 1: raise SystemExit('CLAUDE.md: %r found %d' % (a[:70], s.count(a)))
